import React from 'react';

/**
 * Ảnh bìa cho bài viết không có ảnh.
 *
 * Gần 600 bài nhập từ MedlinePlus là chữ thuần: nguồn không kèm ảnh dùng lại
 * được, và ảnh minh hoạ y khoa lấy bừa trên mạng thì vừa vướng bản quyền vừa
 * có nguy cơ gắn ảnh sai bệnh vào bài — lỗi nặng hơn nhiều so với việc trang
 * nhìn hơi nhạt. Nhưng một feed toàn thẻ chữ trắng thì lướt nhanh không phân
 * biệt được bài nào với bài nào.
 *
 * Giải pháp: một dải màu theo chuyên mục, có icon y khoa thật.
 *
 * Icon lấy từ Health Icons (healthicons.org) của Resolve to Save Lives —
 * giấy phép MIT, bộ icon do các tổ chức y tế công dùng. Đường vẽ được nhúng
 * thẳng vào file này nên không gọi mạng, không phụ thuộc gói ngoài, không có
 * link nào để hỏng. Bản quyền: MIT,
 * https://github.com/resolvetosavelives/healthicons/blob/main/LICENSE
 *
 * Bài nào có ảnh thật thì ảnh thật thắng — component này chỉ chen vào khi
 * không còn gì khác để hiện.
 */

/** djb2: băm chuỗi thành số nguyên ổn định, cùng đầu vào luôn ra cùng kết quả. */
function hashOf(value: string): number {
  let h = 5381;
  for (let i = 0; i < value.length; i += 1) {
    h = ((h << 5) + h + value.charCodeAt(i)) >>> 0;
  }
  return h;
}

