function bodyFor(label: string): string {
  return ICON_BODY[CATEGORY_ICON[label] ?? FALLBACK_ICON] ?? ICON_BODY[FALLBACK_ICON];
}

interface CategoryCoverProps {
  /** Quyết định vị trí hoạ tiết chìm — hai bài cùng chuyên mục vẫn khác nhau. */
  title: string;
  /** Quyết định màu và icon. Thiếu thì rơi về nhãn chung. */
  category?: string | null;
  className?: string;
}

export const CategoryCover: React.FC<CategoryCoverProps> = ({ title, category, className = '' }) => {
  const label = (category || 'Cẩm nang sức khỏe').trim();
  const hue = HUES[hashOf(label) % HUES.length];
  const body = bodyFor(label);

  // Hoạ tiết chìm lệch đi một chút theo tiêu đề. Không có bước này thì mười
  // bài cùng chuyên mục xếp liền nhau cho ra mười dải giống hệt.
  const seed = hashOf(title);
  const shiftX = -40 + (seed % 5) * 12;
  const shiftY = -46 + ((seed >> 4) % 5) * 10;
  const spin = ((seed >> 8) % 5) * 4 - 8;

  const tint = `hsl(${hue} 52% 96%)`;
  const edge = `hsl(${hue} 35% 88%)`;
  const bar = `hsl(${hue} 58% 46%)`;
  const ink = `hsl(${hue} 55% 36%)`;
  const ghost = `hsl(${hue} 50% 45%)`;

  return (
    <div
      className={`relative overflow-hidden rounded-xl border ${className}`}
      style={{ background: tint, borderColor: edge }}
    >
      {/* Hoạ tiết chìm, tràn khỏi mép phải. aria-hidden: đây là trang trí. */}
      <svg
        viewBox="0 0 48 48"
        aria-hidden="true"
        className="absolute w-[210px] h-[210px] pointer-events-none"
        style={{
          right: shiftX,
          top: shiftY,
          color: ghost,
          opacity: 0.1,
          transform: `rotate(${spin}deg)`,
        }}
        dangerouslySetInnerHTML={{ __html: body }}
      />

      <div className="absolute left-0 top-0 bottom-0 w-[5px]" style={{ background: bar }} />

      <div className="absolute inset-0 flex items-center gap-4 sm:gap-5 pl-7 sm:pl-9 pr-5">
        <svg
          viewBox="0 0 48 48"
          aria-hidden="true"
          className="w-12 h-12 sm:w-16 sm:h-16 shrink-0"
          style={{ color: ink }}
          dangerouslySetInnerHTML={{ __html: body }}
        />
        <span
          className="text-[11px] sm:text-[13px] font-extrabold uppercase tracking-[0.12em] leading-snug line-clamp-2"
          style={{ color: `hsl(${hue} 45% 34%)` }}
        >
          {label}
        </span>
      </div>
    </div>
  );
};

export default CategoryCover;
